<?php
require __DIR__.'/bootstrap.php';require __DIR__.'/capture-core.php';
if(!authorized()){http_response_code(403);exit('Administrator access required.');}
$_SESSION['last_seen']=time();$actor=$config['admin_username'];$message='';$error='';$db=db();
function h($s): string {return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}
function field(string $name,string $value='',string $type='text',bool $required=true): string {return '<input name="'.h($name).'" type="'.h($type).'" value="'.h($value).'" '.($required?'required':'').' autocomplete="'.($type==='password'?'new-password':'off').'">';}
function csrf(): string {return '<input type="hidden" name="csrf" value="'.h($_SESSION['csrf']).'">';}
try {
 if($_SERVER['REQUEST_METHOD']==='POST'){
  if(!hash_equals($_SESSION['csrf'],(string)($_POST['csrf']??'')))throw new CaptureError('Invalid token. Reload.',403);
  $action=$_POST['action']??'';$id=(int)($_POST['id']??0);$db->beginTransaction();
  if(in_array($action,['create','edit','delete'],true)){
   $previous=null;if($action!=='create'){$s=$db->prepare('SELECT * FROM quorum_assistants WHERE id=? FOR UPDATE');$s->execute([$id]);$previous=$s->fetch(PDO::FETCH_ASSOC);if(!$previous)throw new CaptureError('Assistant not found.');}
   if($action==='delete'){
    $s=$db->prepare('SELECT COUNT(*) FROM quorum_capture_audit WHERE assistant_id=?');$s->execute([$id]);if((int)$s->fetchColumn()>0)throw new CaptureError('This account has activity. Deactivate it to retain attribution.');
    $db->prepare('DELETE FROM quorum_assistants WHERE id=?')->execute([$id]);cap_audit($db,$actor,'ASSISTANT_DELETED',['id'=>$id,'username'=>$previous['username']]);
   }else {
    $username=cap_text($_POST['username']??'',100);$name=cap_text($_POST['display_name']??'',120);$password=(string)($_POST['password']??'');
    if(!preg_match('/^[A-Za-z0-9_.@-]{3,100}$/D',$username)||$name==='')throw new CaptureError('Use a 3–100 character username (letters, digits, dot, @, hyphen, underscore) and a display name.');
    if(strcasecmp($username,$config['admin_username'])===0)throw new CaptureError('Assistant username must differ from the administrator username.');
    if(($action==='create'||$password!=='')&&(strlen($password)<16||strlen($password)>72))throw new CaptureError('Assistant passwords must be 16–72 characters.');
    $active=isset($_POST['active'])?1:0;$assigned=isset($_POST['assigned'])?1:0;
    if($action==='create'){$db->prepare('INSERT INTO quorum_assistants (username,display_name,password_hash,active,assigned) VALUES (?,?,?,?,?)')->execute([$username,$name,password_hash($password,PASSWORD_DEFAULT),$active,$assigned]);$id=(int)$db->lastInsertId();}
    else {$hash=$password!==''?password_hash($password,PASSWORD_DEFAULT):$previous['password_hash'];$db->prepare('UPDATE quorum_assistants SET username=?,display_name=?,password_hash=?,active=?,assigned=?,version=version+1 WHERE id=?')->execute([$username,$name,$hash,$active,$assigned,$id]);}
    cap_audit($db,$actor,$action==='create'?'ASSISTANT_CREATED':'ASSISTANT_UPDATED',['id'=>$id,'username'=>$username,'active'=>$active,'assigned'=>$assigned,'passwordReset'=>$password!=='']);
   }
  }elseif(in_array($action,['resolve','reopen'],true)){
   [$revision,$state]=cap_lock($db);$reason=cap_text($_POST['reason']??'',2000);
   if($action==='resolve'){$winner=($_POST['winner']??'')==='none'?null:(int)($_POST['winner']??0);cap_resolve($db,$state,$id,$winner,$reason,$actor);}
   else {cap_open($state);if(strlen($reason)<5)throw new CaptureError('Enter the reason for reopening.');$db->prepare("UPDATE quorum_capture_cases SET status='disputed',winner=NULL,reason=?,actor=?,decided_at=? WHERE owner_id=?")->execute([$reason,$actor,cap_time(),$id]);cap_audit($db,$actor,'REPRESENTATION_REOPENED',['ownerId'=>$id,'reason'=>$reason]);}
   cap_store($db,$revision,$state);
  }else throw new CaptureError('Unknown operation.');
  $db->commit();header('Location: assistants.php?saved=1',true,303);exit;
 }
 if(isset($_GET['export'])){
  header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="quorum-capture-audit.csv"');$f=fopen('php://output','w');fwrite($f,"\xEF\xBB\xBF");fputcsv($f,['ID','Assistant ID','Actor','Action','Details','UTC']);
  foreach($db->query('SELECT * FROM quorum_capture_audit ORDER BY id') as $r){$cells=array_map(function($v){$s=(string)$v;return preg_match('/^[=+@\-\t\r]/',$s)?"'".$s:$s;},[$r['id'],$r['assistant_id'],$r['actor'],$r['action'],$r['details'],$r['created_at']]);fputcsv($f,$cells);}exit;
 }
 if(isset($_GET['evidence'])){
  $db->beginTransaction();[, $state]=cap_lock($db);$export=['meeting'=>$state['meeting'],'generatedAt'=>cap_time(),'claims'=>cap_claims($db),'votes'=>cap_votes($db),'decisions'=>$db->query('SELECT * FROM quorum_capture_cases')->fetchAll(PDO::FETCH_ASSOC),'events'=>$db->query('SELECT * FROM quorum_capture_audit ORDER BY id')->fetchAll(PDO::FETCH_ASSOC)];$db->commit();header('Content-Type: application/json');header('Content-Disposition: attachment; filename="quorum-capture-evidence.json"');echo cap_json($export);exit;
 }
 $accounts=$db->query('SELECT id,username,display_name,active,assigned FROM quorum_assistants ORDER BY display_name')->fetchAll(PDO::FETCH_ASSOC);
 $db->beginTransaction();[, $state]=cap_lock($db);$claims=cap_claims($db);$votes=cap_votes($db);$cases=$db->query('SELECT * FROM quorum_capture_cases ORDER BY status,owner_id')->fetchAll(PDO::FETCH_ASSOC);$db->commit();
}catch(Throwable $e){if($db->inTransaction())$db->rollBack();if($e instanceof CaptureError)$error=$e->getMessage();elseif($e instanceof PDOException&&$e->getCode()==='23000')$error='Username already exists or this record has retained activity.';else {error_log('Quorum assistant administration: '.$e->getMessage());$error='Administration unavailable. Confirm the schema upgrade and check server logs.';}$accounts=$accounts??[];$cases=$cases??[];$state=$state??['owners'=>[]];$claims=$claims??[];$votes=$votes??[];}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quorum · Assistants and disputes</title><style>body{font:15px system-ui;background:#f4f7f5;color:#163d32;max-width:1100px;margin:auto;padding:20px}section,details{background:white;border:1px solid #d6e0d9;border-radius:10px;padding:18px;margin:18px 0}label{display:block;margin:12px 0 4px}input:not([type=checkbox]),select,textarea{font:inherit;padding:9px;box-sizing:border-box;width:100%;max-width:600px}button,a.button{display:inline-block;padding:10px 16px;background:#174c3e;color:white;border:0;border-radius:5px;margin:10px 8px 0 0;cursor:pointer}a{color:#174c3e}.error{background:#ffe0d9;padding:16px}table{border-collapse:collapse;width:100%}td,th{padding:8px;border-bottom:1px solid #ddd;text-align:left}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px}.danger{background:#8d332c}.notice{padding:12px;background:#fff1ce}summary{cursor:pointer;font-weight:bold}</style></head><body>
<a href="index.php">← Administrator workspace</a><h1>Assistants &amp; representation disputes</h1><p>Every assistant has both venue check-in and paper-vote capture. No assistant has dashboard, account-management, export, eligibility-editing, or dispute-resolution access.</p><p>Assistant login: <a href="assistant.php">https://gemb.co.za/vote/assistant.php</a>. Use a separate browser/profile when testing an assistant account; one browser session has one role.</p>
<?php if($error): ?><p class="error" role="alert"><?=h($error)?></p><?php endif ?><?php if(isset($_GET['saved'])): ?><p>Change saved.</p><?php endif ?>
<section><h2>Appoint assistant</h2><form method="post"><?=csrf()?><input type="hidden" name="action" value="create"><div class="grid"><div><label>Username</label><?=field('username')?></div><div><label>Display name</label><?=field('display_name')?></div><div><label>Initial password (16–72 characters)</label><?=field('password','','password')?></div></div><label><input type="checkbox" name="active" checked> Account active</label><label><input type="checkbox" name="assigned" checked> Appointed to this meeting workspace</label><button>Create assistant</button></form></section>
<h2>Appointed assistants</h2>
<?php foreach($accounts as $a): ?><details><summary><?=h($a['display_name'])?> · <?=h($a['username'])?> · <?=$a['active']&&$a['assigned']?'Enabled':'Disabled / unassigned'?></summary><form method="post"><?=csrf()?><input type="hidden" name="action" value="edit"><input type="hidden" name="id" value="<?=h($a['id'])?>"><label>Username</label><?=field('username',$a['username'])?><label>Display name</label><?=field('display_name',$a['display_name'])?><label>New password (leave blank to retain)</label><?=field('password','','password',false)?><label><input type="checkbox" name="active" <?=$a['active']?'checked':''?>> Account active</label><label><input type="checkbox" name="assigned" <?=$a['assigned']?'checked':''?>> Appointed to this meeting</label><p>Saving changes invalidates this assistant’s existing sessions.</p><button>Save assistant</button></form><form method="post"><?=csrf()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=h($a['id'])?>"><button class="danger">Delete unused account</button><small>Accounts with activity must be deactivated to preserve attribution.</small></form></details><?php endforeach ?>
<h2>Representation disputes</h2><p>Submission order does not establish authority. Disputed votes and attendance are held until adjudication. A decision applies to that owner’s representation for this meeting, including all motions.</p>
<?php if(!$cases): ?><p>No representation disputes.</p><?php endif ?>
<?php foreach($cases as $case): $oid=(int)$case['owner_id'];$o=null;foreach($state['owners'] as $candidate)if($candidate['id']===$oid)$o=$candidate;$cs=array_values(array_filter($claims,fn($c)=>$c['ownerId']===$oid)); ?>
<section><h3><?=h(($o['unit']??$oid).' — '.($o['name']??'Unknown owner'))?> · <?=h(strtoupper($case['status']))?></h3><p><?=h($case['reason'])?></p><p>Last recorded by <?=h($case['actor'])?> · <?=h($case['decided_at'])?></p>
<?php foreach($cs as $c): ?><details open><summary>Claim <?=h($c['claimId'])?> · <?=h($c['mode']==='proxy'?'Proxy: '.$c['holder']:'Owner')?> · <?=h($c['active']?'Checked in':'Not currently checked in')?></summary><p>Reference: <?=h($c['reference']??'')?> · Captured by <?=h($c['checkedInBy']??'')?> · <?=h($c['checkedInAt']??'')?></p><table><thead><tr><th>Motion</th><th>Choice</th><th>Method / paper reference</th><th>Operator / UTC</th></tr></thead><tbody><?php foreach($votes as $v): if((int)$v['claim_id']!==$c['claimId'])continue; ?><tr><td><?=h($v['motion_id'])?></td><td><?=h($v['choice'])?></td><td><?=h($v['channel'].' / '.($v['paper_reference']??''))?></td><td><?=h($v['actor'].' / '.$v['captured_at'])?></td></tr><?php endforeach ?></tbody></table></details><?php endforeach ?>
<form method="post"><?=csrf()?><input type="hidden" name="action" value="resolve"><input type="hidden" name="id" value="<?=$oid?>"><label>Authorised representation</label><select name="winner" required><option value="">Choose after reviewing evidence</option><?php foreach($cs as $c): ?><option value="<?=$c['claimId']?>">Claim <?=$c['claimId']?> — <?=h($c['mode']==='proxy'?'Proxy: '.$c['holder'].' · '.$c['reference']:'Owner')?></option><?php endforeach ?><option value="none">Neither representation established — exclude both</option></select><label>Evidence reviewed and decision reason</label><textarea name="reason" required minlength="5" maxlength="2000"></textarea><button>Record decision and recalculate</button></form>
<?php if($case['status']==='resolved'): ?><form method="post"><?=csrf()?><input type="hidden" name="action" value="reopen"><input type="hidden" name="id" value="<?=$oid?>"><label>Reason for reopening</label><?=field('reason')?><button>Reopen dispute and hold votes</button></form><?php endif ?></section><?php endforeach ?>
<section><h2>Capture audit and evidence</h2><a class="button" href="assistants.php?export=1">Download capture audit CSV</a><a class="button" href="assistants.php?evidence=1">Download all claims, votes and decisions JSON</a><p>The evidence export retains accepted, disputed and rejected submissions. Ordinary results include only the authorised representation.</p></section></body></html>
